"use strict";const XZ_DEG=Math.PI/180,XZ_RAD=180/Math.PI;function xz_norm360(t){return(t%360+360)%360}function xjAscCalc(t,n,s){const o=(t-2451545)/36525,e=280.46061837+360.98564736629*(t-2451545)+387933e-9*o*o-o*o*o/3871e4,c=xz_norm360(e+n),r=23.439291111-.013004167*o-1639e-10*o*o+5036e-10*o*o*o,a=r*XZ_DEG,i=s*XZ_DEG,l=c*XZ_DEG,u=Math.cos(l),m=-(Math.sin(l)*Math.cos(a)+Math.tan(i)*Math.sin(a)),p=xz_norm360(Math.atan2(u,m)*XZ_RAD),M=xz_norm360(Math.atan2(Math.sin(l),Math.cos(l)*Math.cos(a))*XZ_RAD);return{lon:p,mc:M,ramc:c,eps:r}}window.xjAscCalc=xjAscCalc;function xz_jdToDate(t){const n=(t-24405875e-1)*864e5;return new Date(n)}function xz_moonLat(t){return Astronomy.EclipticGeoMoon(Astronomy.MakeTime(xz_jdToDate(t))).lat}function xz_meanNode(t){const n=(t-2451545)/36525;return((125.0445479-1934.1362891*n+.0020754*n*n+n*n*n/467441-n*n*n*n/60616e3)%360+360)%360}function xz_latCross(t,n){for(let s=0;s<40;s++){const o=(t+n)/2;xz_moonLat(o)<0?t=o:n=o}return(t+n)/2}function xz_moonNodes(t){const o=[];let e=t-15.5,c=xz_moonLat(e);for(let u=e+.5;u<=t+15.5;u+=.5){const m=xz_moonLat(u);c<0&&m>=0&&o.push(xz_latCross(e,u)),e=u,c=m}if(!o.length)return{rahu:xz_meanNode(t),ketu:(xz_meanNode(t)+180)%360};let r=o[0];for(const u of o)Math.abs(u-t)<Math.abs(r-t)&&(r=u);const i=(Astronomy.EclipticGeoMoon(Astronomy.MakeTime(xz_jdToDate(r))).lon%360+360)%360,l=xz_norm360(i-.0529539*(t-r));return{rahu:l,ketu:xz_norm360(l+180)}}function xz_ephem_eclip(t){const n=Astronomy.MakeTime(xz_jdToDate(t)),s={},o=Astronomy.SunPosition(n);s.sun={lon:xz_norm360(o.elon),lat:o.elat};const e=Astronomy.EclipticGeoMoon(n);s.moon={lon:xz_norm360(e.lon),lat:e.lat};const c={mercury:"Mercury",venus:"Venus",mars:"Mars",jupiter:"Jupiter",saturn:"Saturn",uranus:"Uranus",neptune:"Neptune",pluto:"Pluto"};for(const r in c){const a=Astronomy.GeoVector(Astronomy.Body[c[r]],n,!0),i=Astronomy.Ecliptic(a);s[r]={lon:xz_norm360(i.elon),lat:i.elat}}return s}function xz_lons10(t){const n=xz_ephem_eclip(t),s={};for(const o in n)s[o]=n[o].lon;return s}function xz_planetLon(t,n){const s=Astronomy.MakeTime(xz_jdToDate(t));if(n==="sun")return xz_norm360(Astronomy.SunPosition(s).elon);if(n==="moon")return xz_norm360(Astronomy.EclipticGeoMoon(s).lon);const o={mercury:"Mercury",venus:"Venus",mars:"Mars",jupiter:"Jupiter",saturn:"Saturn",uranus:"Uranus",neptune:"Neptune",pluto:"Pluto"},e=Astronomy.GeoVector(Astronomy.Body[o[n]],s,!0);return xz_norm360(Astronomy.Ecliptic(e).elon)}function xz_ephem_longitudes(t){const n=xz_lons10(t),s=xz_moonNodes(t);return n.rahu=s.rahu,n.ketu=s.ketu,n}function xz_ephem_speeds(t){const n=xz_lons10(t-.5),s=xz_lons10(t+.5),o={};for(const e in n){let c=s[e]-n[e];c>180?c-=360:c<-180&&(c+=360),o[e]=c}return o}function xz_ephem_declinations(t){const n=xz_ephem_eclip(t),s=(t-2451545)/36525,o=23.439291111-.013004167*s-1639e-10*s*s+5036e-10*s*s*s,e=o*XZ_DEG,c={};for(const r in n){const a=n[r].lat*XZ_DEG,i=n[r].lon*XZ_DEG;c[r]=Math.asin(Math.sin(a)*Math.cos(e)+Math.cos(a)*Math.sin(e)*Math.sin(i))*XZ_RAD}return{dec:c,eps:o}}
